import{_ as n,a0 as p,w as r,s as d,ao as l,I as o,x as t,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何進行 Linux 啓動時間優化 | LCTT x X-CMD","titleTemplate":false,"description":"如何進行 Linux 啓動時間優化 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何進行 Linux 啓動時間優化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何進行 Linux 啓動時間優化 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20191022 How to Go About Linux Boot Time Optimisation","title":"如何進行 Linux 啓動時間優化","tag":"202002","desc":""},"relativePath":"202002/20191022 How to Go About Linux Boot Time Optimisation.md","filePath":"[post].md"}'),c={name:"202002/20191022 How to Go About Linux Boot Time Optimisation.md"};function u(h,e,g,b,m,f){const i=p("Link");return r(),d("div",null,[e[21]||(e[21]=l('<h1 id="如何進行-linux-啓動時間優化" tabindex="-1">如何進行 Linux 啓動時間優化 <a class="header-anchor" href="#如何進行-linux-啓動時間優化" aria-label="Permalink to “如何進行 Linux 啓動時間優化”">​</a></h1><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/Screenshot-from-2019-10-07-13-16-32.png?fit=700%2C499&amp;ssl=1" alt=""></p><blockquote><p>快速啓動嵌入式設備或電信設備，對於時間要求緊迫的應用程序是至關重要的，並且在改善用户體驗方面也起着非常重要的作用。這個文章給予一些關於如何增強任意設備的啓動時間的重要技巧。</p></blockquote><p>快速啓動或快速重啓在各種情況下起着至關重要的作用。為了保持所有服務的高可用性和更好的性能，嵌入式設備的快速啓動至關重要。設想有一台運行着沒有啓用快速啓動的 Linux 操作系統的電信設備，所有依賴於這個特殊嵌入式設備的系統、服務和用户可能會受到影響。這些設備維持其服務的高可用性是非常重要的，為此，快速啓動和重啓起着至關重要的作用。</p><p>一台電信設備的一次小故障或關機，即使只是幾秒鐘，都可能會對無數互聯網上的用户造成破壞。因此，對於很多對時間要求嚴格的設備和電信設備來説，在它們的設備中加入快速啓動的功能以幫助它們快速恢復工作是非常重要的。讓我們從圖 1 中理解 Linux 啓動過程。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-1.png?ssl=1" alt="圖 1：啓動過程"></p><h3 id="監視工具和啓動過程" tabindex="-1">監視工具和啓動過程 <a class="header-anchor" href="#監視工具和啓動過程" aria-label="Permalink to “監視工具和啓動過程”">​</a></h3><p>在對機器做出更改之前，用户應注意許多因素。其中包括計算機的當前啓動速度，以及佔用資源並增加啓動時間的服務、進程或應用程序。</p><h4 id="啓動圖" tabindex="-1">啓動圖 <a class="header-anchor" href="#啓動圖" aria-label="Permalink to “啓動圖”">​</a></h4><p>為監視啓動速度和在啓動期間啓動的各種服務，用户可以使用下面的命令來安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install pybootchartgui</span></span></code></pre></div><p>你每次啓動時，啓動圖會在日誌中保存一個 png 文件，使用户能夠查看該 png 文件來理解系統的啓動過程和服務。為此，使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /var/log/bootchart</span></span></code></pre></div><p>用户可能需要一個應用程序來查看 png 文件。Feh 是一個面向控制台用户的 X11 圖像查看器。不像大多數其它的圖像查看器，它沒有一個精緻的圖形用户界面，但它只用來顯示圖片。Feh 可以用於查看 png 文件。你可以使用下面的命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install feh</span></span></code></pre></div><p>你可以使用 <code>feh xxxx.png</code> 來查看 png 文件。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-2.png?ssl=1" alt="圖 2：啓動圖"></p><p>圖 2 顯示了一個正在查看的引導圖 png 文件。</p><h4 id="systemd-analyze" tabindex="-1">systemd-analyze <a class="header-anchor" href="#systemd-analyze" aria-label="Permalink to “systemd-analyze”">​</a></h4><p>但是，對於 Ubuntu 15.10 以後的版本不再需要引導圖。為獲取關於啓動速度的簡短信息，使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemd-analyze</span></span></code></pre></div><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-3.png?ssl=1" alt="圖 3：systemd-analyze 的輸出"></p><p>圖表 3 顯示命令 <code>systemd-analyze</code> 的輸出。</p><p>命令 <code>systemd-analyze blame</code> 用於根據初始化所用的時間打印所有正在運行的單元的列表。這個信息是非常有用的，可用於優化啓動時間。<code>systemd-analyze blame</code> 不會顯示服務類型為簡單（<code>Type=simple</code>）的服務，因為 systemd 認為這些服務應是立即啓動的；因此，無法測量初始化的延遲。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-4.png?ssl=1" alt="圖 4：systemd-analyze blame 的輸出"></p><p>圖 4 顯示 <code>systemd-analyze blame</code> 的輸出。</p><p>下面的命令打印時間關鍵的服務單元的樹形鏈條：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command systemd-analyze critical-chain</span></span></code></pre></div><p>圖 5 顯示命令 <code>systemd-analyze critical-chain</code> 的輸出。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-5.png?ssl=1" alt="圖 5：systemd-analyze critical-chain 的輸出"></p><h3 id="減少啓動時間的步驟" tabindex="-1">減少啓動時間的步驟 <a class="header-anchor" href="#減少啓動時間的步驟" aria-label="Permalink to “減少啓動時間的步驟”">​</a></h3><p>下面顯示的是一些可以減少啓動時間的各種步驟。</p><h4 id="bum-啓動管理器" tabindex="-1">BUM（啓動管理器） <a class="header-anchor" href="#bum-啓動管理器" aria-label="Permalink to “BUM（啓動管理器）”">​</a></h4><p>BUM 是一個運行級配置編輯器，允許在系統啓動或重啓時配置初始化服務。它顯示了可以在啓動時啓動的每個服務的列表。用户可以打開和關閉各個服務。BUM 有一個非常清晰的圖形用户界面，並且非常容易使用。</p><p>在 Ubuntu 14.04 中，BUM 可以使用下面的命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install bum</span></span></code></pre></div>',36)),o("p",null,[e[1]||(e[1]=t("為在 15.10 以後的版本中安裝它，從鏈接 ",-1)),s(i,{href:"http://apt.ubuntu.com/p/bum"},{default:a(()=>[...e[0]||(e[0]=[t("http://apt.ubuntu.com/p/bum",-1)])]),_:1}),e[2]||(e[2]=t(" 下載軟件包。",-1))]),e[22]||(e[22]=l('<p>以基本的服務開始，禁用掃描儀和打印機相關的服務。如果你沒有使用藍牙和其它不想要的設備和服務，你也可以禁用它們中一些。我強烈建議你在禁用相關的服務前學習服務的基礎知識，因為這可能會影響計算機或操作系統。圖 6 顯示 BUM 的圖形用户界面。</p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-6.png?ssl=1" alt="圖 6：BUM"></p><h4 id="編輯-rc-文件" tabindex="-1">編輯 rc 文件 <a class="header-anchor" href="#編輯-rc-文件" aria-label="Permalink to “編輯 rc 文件”">​</a></h4><p>要編輯 rc 文件，你需要轉到 rc 目錄。這可以使用下面的命令來做到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /etc/init.d</span></span></code></pre></div><p>然而，訪問 <code>init.d</code> 需要 root 用户權限，該目錄基本上包含的是開始/停止腳本，這些腳本用於在系統運行時或啓動期間控制（開始、停止、重新加載、啓動啓動）守護進程。</p><p>在 <code>init.d</code> 目錄中的 <code>rc</code> 文件被稱為<ruby>運行控制<rt>run control</rt></ruby>腳本。在啓動期間，<code>init</code> 執行 <code>rc</code> 腳本併發揮它的作用。為改善啓動速度，我們可以更改 <code>rc</code> 文件。使用任意的文件編輯器打開 <code>rc</code> 文件（當你在 <code>init.d</code> 目錄中時）。</p><p>例如，通過輸入 <code>vim rc</code> ，你可以更改 <code>CONCURRENCY=none</code> 為 <code>CONCURRENCY=shell</code>。後者允許某些啓動腳本同時執行，而不是依序執行。</p><p>在最新版本的內核中，該值應該被更改為 <code>CONCURRENCY=makeﬁle</code>。</p><p>圖 7 和圖 8 顯示編輯 <code>rc</code> 文件前後的啓動時間比較。可以注意到啓動速度有所提高。在編輯 <code>rc</code> 文件前的啓動時間是 50.98 秒，然而在對 <code>rc</code> 文件進行更改後的啓動時間是 23.85 秒。</p><p>但是，上面提及的更改方法在 Ubuntu 15.10 以後的操作系統上不工作，因為使用最新內核的操作系統使用 systemd 文件，而不再是 <code>init.d</code> 文件。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-7.png?ssl=1" alt="圖 7：對 rc 文件進行更改之前的啓動速度"></p><p><img src="https://i1.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-8.png?ssl=1" alt="圖 8：對 rc 文件進行更改之後的啓動速度"></p><h4 id="e4rat" tabindex="-1">E4rat <a class="header-anchor" href="#e4rat" aria-label="Permalink to “E4rat”">​</a></h4><p>E4rat 代表 e4 <ruby>減少訪問時間<rt>reduced access time</rt></ruby>（僅在 ext4 文件系統的情況下）。它是由 Andreas Rid 和 Gundolf Kiefer 開發的一個項目。E4rat 是一個通過碎片整理來幫助快速啓動的應用程序。它還會加速應用程序的啓動。E4rat 使用物理文件的重新分配來消除尋道時間和旋轉延遲，因而達到較高的磁盤傳輸速度。</p>',15)),o("p",null,[e[4]||(e[4]=t("E4rat 可以 .deb 軟件包形式獲得，你可以從它的官方網站 ",-1)),s(i,{href:"http://e4rat.sourceforge.net/"},{default:a(()=>[...e[3]||(e[3]=[t("http://e4rat.sourceforge.net/",-1)])]),_:1}),e[5]||(e[5]=t(" 下載。",-1))]),e[23]||(e[23]=l('<p>Ubuntu 默認安裝的 ureadahead 軟件包與 e4rat 衝突。因此必須使用下面的命令安裝這幾個軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg purge ureadahead ubuntu-minimal</span></span></code></pre></div><p>現在使用下面的命令來安裝 e4rat 的依賴關係：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install libblkid1 e2fslibs</span></span></code></pre></div><p>打開下載的 .deb 文件，並安裝它。現在需要恰當地收集啓動數據來使 e4rat 工作。</p><p>遵循下面所給的步驟來使 e4rat 正確地運行並提高啓動速度。</p><ul><li>在啓動期間訪問 Grub 菜單。這可以在系統啓動時通過按住 <code>shift</code> 按鍵來完成。</li><li>選擇通常用於啓動的選項（內核版本），並按 <code>e</code>。</li><li>查找以 <code>linux /boot/vmlinuz</code> 開頭的行，並在該行的末尾添加下面的代碼（在句子的最後一個字母后按空格鍵）：<code>init=/sbin/e4rat-collect or try - quiet splash vt.handsoff =7 init=/sbin/e4rat-collect </code>。</li><li>現在，按 <code>Ctrl+x</code> 來繼續啓動。這可以讓 e4rat 在啓動後收集數據。在這台機器上工作，並在接下來的兩分鐘時間內打開並關閉應用程序。</li><li>通過轉到 e4rat 文件夾，並使用下面的命令來訪問日誌文件：<code>cd /var/log/e4rat</code>。</li><li>如果你沒有找到任何日誌文件，重複上面的過程。一旦日誌文件就緒，再次訪問 Grub 菜單，並對你的選項按 <code>e</code>。</li><li>在你之前已經編輯過的同一行的末尾輸入 <code>single</code>。這可以讓你訪問命令列。如果出現其它菜單，選擇恢復正常啓動（Resume normal boot）。如果你不知為何不能進入命令提示符，按 <code>Ctrl+Alt+F1</code> 組合鍵。</li><li>在你看到登錄提示後，輸入你的登錄信息。</li><li>現在輸入下面的命令：<code>sudo e4rat-realloc /var/lib/e4rat/startup.log</code>。此過程需要一段時間，具體取決於機器的磁盤速度。</li><li>現在使用下面的命令來重啓你的機器：<code>sudo shutdown -r now</code>。</li><li>現在，我們需要配置 Grub 來在每次啓動時運行 e4rat。</li><li>使用任意的編輯器訪問 grub 文件。例如，<code>gksu gedit /etc/default/grub</code>。</li><li>查找以 <code>GRUB CMDLINE LINUX DEFAULT=</code> 開頭的一行，並在引號之間和任何選項之前添加下面的行：<code>init=/sbin/e4rat-preload 18</code>。</li><li>它應該看起來像這樣：<code>GRUB CMDLINE LINUX DEFAULT = init=/sbin/e4rat- preload quiet splash</code>。</li><li>保存並關閉 Grub 菜單，並使用 <code>sudo update-grub</code> 更新 Grub 。</li><li>重啓系統，你將發現啓動速度有明顯變化。</li></ul><p>圖 9 和圖 10 顯示在安裝 e4rat 前後的啓動時間之間的差異。可注意到啓動速度的提高。在使用 e4rat 前啓動所用時間是 22.32 秒，然而在使用 e4rat 後啓動所用時間是 9.065 秒。</p><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-9.png?ssl=1" alt="圖 9：使用 e4rat 之前的啓動速度"></p><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/fig-10.png?ssl=1" alt="圖 10：使用 e4rat 之後的啓動速度"></p><h3 id="一些易做的調整" tabindex="-1">一些易做的調整 <a class="header-anchor" href="#一些易做的調整" aria-label="Permalink to “一些易做的調整”">​</a></h3><p>使用很小的調整也可以達到良好的啓動速度，下面列出其中兩個。</p><h4 id="ssd" tabindex="-1">SSD <a class="header-anchor" href="#ssd" aria-label="Permalink to “SSD”">​</a></h4><p>使用固態設備而不是普通的硬盤或者其它的存儲設備將肯定會改善啓動速度。SSD 也有助於加快文件傳輸和運行應用程序方面的速度。</p><h4 id="禁用圖形用户界面" tabindex="-1">禁用圖形用户界面 <a class="header-anchor" href="#禁用圖形用户界面" aria-label="Permalink to “禁用圖形用户界面”">​</a></h4><p>圖形用户界面、桌面圖形和窗口動畫佔用大量的資源。禁用圖形用户界面是獲得良好的啓動速度的另一個好方法。</p><hr>',17)),o("p",null,[e[7]||(e[7]=t("via: ",-1)),s(i,{href:"https://opensourceforu.com/2019/10/how-to-go-about-linux-boot-time-optimisation/"},{default:a(()=>[...e[6]||(e[6]=[t("https://opensourceforu.com/2019/10/how-to-go-about-linux-boot-time-optimisation/",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("作者：",-1)),s(i,{href:"https://opensourceforu.com/author/b-thangaraju/"},{default:a(()=>[...e[8]||(e[8]=[t("B Thangaraju",-1)])]),_:1}),e[13]||(e[13]=t(" 選題：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),s(i,{href:"https://github.com/robsean"},{default:a(()=>[...e[10]||(e[10]=[t("robsean",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:a(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const C=n(c,[["render",u]]);export{x as __pageData,C as default};
